def sorted_squares(nums):
    n = len(nums)
    out = [0] * n
    lo, hi, p = 0, n - 1, n - 1
    while lo <= hi:
        a, b = nums[lo] * nums[lo], nums[hi] * nums[hi]
        if a >= b:
            out[p] = a; lo += 1
        else:
            out[p] = b; hi -= 1
        p -= 1
    return out

for _ in range(500):
